=== FILE: axil_timer.v ===
// axil_timer: 32-bit down-counting timer with one-shot and periodic modes
// and a level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md as planned in microarchitecture.md.

module axil_timer #(
    parameter ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,

    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,

    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,

    output wire                  irq
);

    localparam [1:0] RESP_OKAY   = 2'b00;
    localparam [1:0] RESP_SLVERR = 2'b10;

    localparam [1:0] IDX_CTRL   = 2'd0;
    localparam [1:0] IDX_LOAD   = 2'd1;
    localparam [1:0] IDX_COUNT  = 2'd2;
    localparam [1:0] IDX_STATUS = 2'd3;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg [ADDR_WIDTH-1:0] aw_addr_q;
    reg                  w_held;
    reg [31:0]           w_data_q;
    reg [3:0]            w_strb_q;

    reg                  en;
    reg                  ie;
    reg                  mode;
    reg                  expired;
    reg [31:0]           load;
    reg [31:0]           count;

    // ------------------------------------------------------------------
    // Channel handshakes
    // ------------------------------------------------------------------
    assign s_axil_awready = !aw_held && !s_axil_bvalid;
    assign s_axil_wready  = !w_held  && !s_axil_bvalid;
    assign s_axil_arready = !s_axil_rvalid;

    wire aw_hs = s_axil_awvalid && s_axil_awready;
    wire w_hs  = s_axil_wvalid  && s_axil_wready;
    wire ar_hs = s_axil_arvalid && s_axil_arready;

    // Both halves of a write present (held or arriving).
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [31:0]           wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [3:0]            wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // ------------------------------------------------------------------
    // Address decode: word aligned and below 0x10
    // ------------------------------------------------------------------
    wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                           ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] wr_idx    = wr_addr[3:2];
    wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                           ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
    wire [1:0] rd_idx    = s_axil_araddr[3:2];

    wire wr_okay  = wr_mapped && (wr_idx != IDX_COUNT);
    wire wr_ctrl  = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
    wire wr_load  = do_write && wr_mapped && (wr_idx == IDX_LOAD);
    wire wr_clear = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                    wr_strb[0] && wr_data[0];

    wire [31:0] load_merged = {
        wr_strb[3] ? wr_data[31:24] : load[31:24],
        wr_strb[2] ? wr_data[23:16] : load[23:16],
        wr_strb[1] ? wr_data[15:8]  : load[15:8],
        wr_strb[0] ? wr_data[7:0]   : load[7:0]
    };

    // Last cycle of a count; a count of 0 is treated like 1.
    wire count_end = en && (count <= 32'd1);

    assign irq = expired && ie;

    // ------------------------------------------------------------------
    // Read data mux
    // ------------------------------------------------------------------
    reg [31:0] rd_value;
    always @* begin
        rd_value = 32'd0;
        if (rd_mapped) begin
            case (rd_idx)
                IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
                IDX_LOAD:   rd_value = load;
                IDX_COUNT:  rd_value = count;
                IDX_STATUS: rd_value = {31'd0, expired};
                default:    rd_value = 32'd0;
            endcase
        end
    end

    // ------------------------------------------------------------------
    // Write channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held       <= 1'b0;
            aw_addr_q     <= {ADDR_WIDTH{1'b0}};
            w_held        <= 1'b0;
            w_data_q      <= 32'd0;
            w_strb_q      <= 4'd0;
            s_axil_bvalid <= 1'b0;
            s_axil_bresp  <= RESP_OKAY;
        end else begin
            if (s_axil_bvalid && s_axil_bready)
                s_axil_bvalid <= 1'b0;
            if (do_write) begin
                aw_held       <= 1'b0;
                w_held        <= 1'b0;
                s_axil_bvalid <= 1'b1;
                s_axil_bresp  <= wr_okay ? RESP_OKAY : RESP_SLVERR;
            end else begin
                if (aw_hs) begin
                    aw_held   <= 1'b1;
                    aw_addr_q <= s_axil_awaddr;
                end
                if (w_hs) begin
                    w_held   <= 1'b1;
                    w_data_q <= s_axil_wdata;
                    w_strb_q <= s_axil_wstrb;
                end
            end
        end
    end

    // ------------------------------------------------------------------
    // Read channel
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            s_axil_rvalid <= 1'b0;
            s_axil_rdata  <= 32'd0;
            s_axil_rresp  <= RESP_OKAY;
        end else begin
            if (s_axil_rvalid && s_axil_rready)
                s_axil_rvalid <= 1'b0;
            if (ar_hs) begin
                s_axil_rvalid <= 1'b1;
                s_axil_rdata  <= rd_value;
                s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
            end
        end
    end

    // ------------------------------------------------------------------
    // Timer (order gives the specified priorities: last assignment wins)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            en      <= 1'b0;
            ie      <= 1'b0;
            mode    <= 1'b0;
            expired <= 1'b0;
            load    <= 32'd0;
            count   <= 32'd0;
        end else begin
            // 1. Count step
            if (en) begin
                if (count_end) begin
                    if (mode) begin
                        count <= load;
                    end else begin
                        count <= 32'd0;
                        en    <= 1'b0;
                    end
                end else begin
                    count <= count - 32'd1;
                end
            end
            // 2. EXPIRED: clear, then set (a count end beats a clear)
            if (wr_clear)
                expired <= 1'b0;
            if (count_end)
                expired <= 1'b1;
            // 3. CTRL write wins for en and count
            if (wr_ctrl) begin
                ie   <= wr_data[1];
                mode <= wr_data[2];
                if (wr_data[0]) begin
                    en    <= 1'b1;
                    count <= load;
                end else begin
                    en <= 1'b0;
                end
            end
            // 4. LOAD byte merge
            if (wr_load)
                load <= load_merged;
        end
    end

`ifdef FORMAL
    // Design-intent invariants (not proven by this submission).
    reg f_reset_seen = 1'b0;
    always @(posedge aclk)
        if (!aresetn)
            f_reset_seen <= 1'b1;

    always @(*) begin
        if (f_reset_seen) begin
            assert (!(aw_held && w_held));
            assert (!(aw_held && s_axil_bvalid));
            assert (!(w_held && s_axil_bvalid));
            assert ((s_axil_bresp == RESP_OKAY) || (s_axil_bresp == RESP_SLVERR));
            assert ((s_axil_rresp == RESP_OKAY) || (s_axil_rresp == RESP_SLVERR));
            assert (irq == (expired && ie));
        end
    end
`endif

endmodule
=== END FILE ===
=== FILE: axil_timer_tb.v ===
// axil_timer_tb: self-checking directed testbench for axil_timer.
// Runs the same suite on an ADDR_WIDTH 4 lane and an ADDR_WIDTH 8 lane.

module axil_timer_tb;

    localparam [7:0] A_CTRL   = 8'h00;
    localparam [7:0] A_LOAD   = 8'h04;
    localparam [7:0] A_COUNT  = 8'h08;
    localparam [7:0] A_STATUS = 8'h0C;
    localparam [1:0] OKAY     = 2'b00;
    localparam [1:0] SLVERR   = 2'b10;

    reg aclk    = 1'b0;
    reg aresetn = 1'b0;
    reg lane    = 1'b0;   // 0: ADDR_WIDTH 4, 1: ADDR_WIDTH 8

    reg [7:0]  awaddr  = 8'h00;
    reg        awvalid = 1'b0;
    reg [31:0] wdata   = 32'h0;
    reg [3:0]  wstrb   = 4'h0;
    reg        wvalid  = 1'b0;
    reg        bready  = 1'b0;
    reg [7:0]  araddr  = 8'h00;
    reg        arvalid = 1'b0;
    reg        rready  = 1'b0;

    wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
    wire [1:0]  bresp4, rresp4;
    wire [31:0] rdata4;
    wire        awready8, wready8, bvalid8, arready8, rvalid8, irq8;
    wire [1:0]  bresp8, rresp8;
    wire [31:0] rdata8;

    axil_timer #(.ADDR_WIDTH(4)) dut4 (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr[3:0]),
        .s_axil_awvalid (awvalid && !lane),
        .s_axil_awready (awready4),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid && !lane),
        .s_axil_wready  (wready4),
        .s_axil_bresp   (bresp4),
        .s_axil_bvalid  (bvalid4),
        .s_axil_bready  (bready && !lane),
        .s_axil_araddr  (araddr[3:0]),
        .s_axil_arvalid (arvalid && !lane),
        .s_axil_arready (arready4),
        .s_axil_rdata   (rdata4),
        .s_axil_rresp   (rresp4),
        .s_axil_rvalid  (rvalid4),
        .s_axil_rready  (rready && !lane),
        .irq            (irq4)
    );

    axil_timer #(.ADDR_WIDTH(8)) dut8 (
        .aclk           (aclk),
        .aresetn        (aresetn),
        .s_axil_awaddr  (awaddr),
        .s_axil_awvalid (awvalid && lane),
        .s_axil_awready (awready8),
        .s_axil_wdata   (wdata),
        .s_axil_wstrb   (wstrb),
        .s_axil_wvalid  (wvalid && lane),
        .s_axil_wready  (wready8),
        .s_axil_bresp   (bresp8),
        .s_axil_bvalid  (bvalid8),
        .s_axil_bready  (bready && lane),
        .s_axil_araddr  (araddr),
        .s_axil_arvalid (arvalid && lane),
        .s_axil_arready (arready8),
        .s_axil_rdata   (rdata8),
        .s_axil_rresp   (rresp8),
        .s_axil_rvalid  (rvalid8),
        .s_axil_rready  (rready && lane),
        .irq            (irq8)
    );

    wire        awready = lane ? awready8 : awready4;
    wire        wready  = lane ? wready8  : wready4;
    wire        bvalid  = lane ? bvalid8  : bvalid4;
    wire [1:0]  bresp   = lane ? bresp8   : bresp4;
    wire        arready = lane ? arready8 : arready4;
    wire        rvalid  = lane ? rvalid8  : rvalid4;
    wire [1:0]  rresp   = lane ? rresp8   : rresp4;
    wire [31:0] rdata   = lane ? rdata8   : rdata4;
    wire        irq     = lane ? irq8     : irq4;

    always #5 aclk = ~aclk;

    // Rising-edge counter: after edge k, cyc == k.
    integer cyc = 0;
    always @(posedge aclk) cyc <= cyc + 1;

    // irq rise monitor: records the edge after which irq rose.
    reg     irq_q    = 1'b0;
    integer rise_cnt = 0;
    integer rise_edge [0:255];
    always @(posedge aclk) begin
        irq_q <= irq;
        if (irq && !irq_q && (rise_cnt < 256)) begin
            rise_edge[rise_cnt] <= cyc;
            rise_cnt <= rise_cnt + 1;
        end
    end

    integer passed = 0;
    integer failed = 0;
    integer last_wr_edge = 0;
    integer last_ar_edge = 0;
    reg [8*64-1:0] nonce;

    // ------------------------------------------------------------------
    // Checking helpers
    // ------------------------------------------------------------------
    task fail(input [8*80-1:0] msg);
        begin
            failed = failed + 1;
            $error("FAIL: %0s", msg);
        end
    endtask

    task chk(input ok, input [8*80-1:0] msg);
        begin
            if (ok === 1'b1) passed = passed + 1;
            else fail(msg);
        end
    endtask

    task chk32(input [31:0] got, input [31:0] exp_d, input [8*80-1:0] msg);
        begin
            if (got === exp_d) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("FAIL: %0s: got 0x%08h, expected 0x%08h", msg, got, exp_d);
            end
        end
    endtask

    function [31:0] merge(input [31:0] old_v, input [31:0] d, input [3:0] s);
        integer k;
        begin
            merge = old_v;
            for (k = 0; k < 4; k = k + 1)
                if (s[k]) merge[8*k +: 8] = d[8*k +: 8];
        end
    endfunction

    task wait_until(input integer target);
        begin
            if (cyc > target) fail("sequencing: target edge already passed");
            while (cyc < target) @(negedge aclk);
        end
    endtask

    task wait_cycles(input integer n);
        begin
            repeat (n) @(negedge aclk);
        end
    endtask

    // ------------------------------------------------------------------
    // Bus tasks: inputs change at negedges, handshakes happen at posedges.
    // ------------------------------------------------------------------
    task axi_write_x(input [7:0] addr, input [31:0] data, input [3:0] strb,
                     input integer aw_delay, input integer w_delay,
                     input integer b_delay, output [1:0] resp);
        integer t;
        integer bcnt;
        reg aw_ok, w_ok, b_ok, bseen, aw_go, w_go, b_go;
        reg [1:0] bfirst;
        begin
            aw_ok = 1'b0; w_ok = 1'b0; b_ok = 1'b0; bseen = 1'b0;
            aw_go = 1'b0; w_go = 1'b0; b_go = 1'b0;
            t = 0; bcnt = 0; bfirst = 2'b00; resp = 2'b11;
            @(negedge aclk);
            while (!b_ok && (t < 200)) begin
                awvalid = !aw_ok && (t >= aw_delay);
                awaddr  = addr;
                wvalid  = !w_ok && (t >= w_delay);
                wdata   = data;
                wstrb   = strb;
                if (bvalid) begin
                    if (!bseen) begin
                        bseen  = 1'b1;
                        bfirst = bresp;
                    end else if (bresp !== bfirst) begin
                        fail("BRESP changed while B was stalled");
                    end
                    bready = (bcnt >= b_delay);
                    bcnt   = bcnt + 1;
                end else begin
                    bready = 1'b0;
                end
                if (bvalid && (awready || wready))
                    fail("AWREADY or WREADY high while a response waits");
                if (aw_ok && !w_ok && awready)
                    fail("AWREADY high while an address is held");
                if (w_ok && !aw_ok && wready)
                    fail("WREADY high while data is held");
                if (bvalid && !(aw_ok && w_ok))
                    fail("BVALID before both halves of the write");
                aw_go = awvalid && awready;
                w_go  = wvalid && wready;
                b_go  = bvalid && bready;
                @(negedge aclk);
                t = t + 1;
                if (aw_go) aw_ok = 1'b1;
                if (w_go)  w_ok  = 1'b1;
                if ((aw_go || w_go) && aw_ok && w_ok) begin
                    last_wr_edge = cyc;
                    chk(bvalid === 1'b1, "BVALID rises on the edge the write completes");
                end
                if (b_go) begin
                    b_ok = 1'b1;
                    resp = bfirst;
                end
            end
            awvalid = 1'b0;
            wvalid  = 1'b0;
            bready  = 1'b0;
            if (!b_ok) fail("write timed out");
        end
    endtask

    task axi_read_x(input [7:0] addr, input integer r_delay,
                    output [31:0] data, output [1:0] resp);
        integer t;
        integer rcnt;
        reg ar_ok, r_ok, rseen, ar_go, r_go;
        reg [31:0] dfirst;
        reg [1:0]  rfirst;
        begin
            ar_ok = 1'b0; r_ok = 1'b0; rseen = 1'b0; ar_go = 1'b0; r_go = 1'b0;
            t = 0; rcnt = 0; dfirst = 32'h0; rfirst = 2'b00;
            data = 32'hDEADDEAD; resp = 2'b11;
            @(negedge aclk);
            while (!r_ok && (t < 200)) begin
                arvalid = !ar_ok;
                araddr  = addr;
                if (rvalid) begin
                    if (!rseen) begin
                        rseen  = 1'b1;
                        dfirst = rdata;
                        rfirst = rresp;
                    end else if ((rdata !== dfirst) || (rresp !== rfirst)) begin
                        fail("RDATA or RRESP changed while R was stalled");
                    end
                    rready = (rcnt >= r_delay);
                    rcnt   = rcnt + 1;
                end else begin
                    rready = 1'b0;
                end
                if (rvalid && arready)
                    fail("ARREADY high while a read response waits");
                if (rvalid && !ar_ok)
                    fail("RVALID without an accepted read");
                ar_go = arvalid && arready;
                r_go  = rvalid && rready;
                @(negedge aclk);
                t = t + 1;
                if (ar_go) begin
                    ar_ok = 1'b1;
                    last_ar_edge = cyc;
                    chk(rvalid === 1'b1, "RVALID rises on the edge AR is accepted");
                end
                if (r_go) begin
                    r_ok = 1'b1;
                    data = dfirst;
                    resp = rfirst;
                end
            end
            arvalid = 1'b0;
            rready  = 1'b0;
            if (!r_ok) fail("read timed out");
        end
    endtask

    task write_expect(input [7:0] a, input [31:0] d, input [3:0] s,
                      input [1:0] exp_resp, input [8*80-1:0] msg);
        reg [1:0] r;
        begin
            axi_write_x(a, d, s, 0, 0, 0, r);
            chk(r === exp_resp, msg);
        end
    endtask

    task rd_expect(input [7:0] a, input [31:0] exp_d, input [1:0] exp_resp,
                   input [8*80-1:0] msg);
        reg [31:0] d;
        reg [1:0]  r;
        begin
            axi_read_x(a, 0, d, r);
            chk32(d, exp_d, msg);
            chk(r === exp_resp, msg);
        end
    endtask

    task do_reset;
        begin
            @(negedge aclk);
            aresetn = 1'b0;
            awvalid = 1'b0;
            wvalid  = 1'b0;
            bready  = 1'b0;
            arvalid = 1'b0;
            rready  = 1'b0;
            @(negedge aclk);
            @(negedge aclk);
            aresetn = 1'b1;
        end
    endtask

    // One-shot count with IE 1, timed to the edge.
    task oneshot_run(input [31:0] n_load);
        integer e;
        integer r0;
        integer len;
        begin
            len = (n_load == 32'd0) ? 32'd1 : n_load;
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "one-shot: clear STATUS");
            write_expect(A_LOAD, n_load, 4'hF, OKAY, "one-shot: write LOAD");
            chk(irq === 1'b0, "one-shot: irq low before start");
            r0 = rise_cnt;
            write_expect(A_CTRL, 32'h3, 4'hF, OKAY, "one-shot: start with IE");
            e = last_wr_edge;
            wait_until(e + len + 3);
            chk(rise_cnt == r0 + 1, "one-shot: exactly one interrupt");
            chk(rise_edge[r0] == e + len, "one-shot: count ends LOAD edges after start");
            rd_expect(A_CTRL, 32'h2, OKAY, "one-shot: EN clears itself");
            rd_expect(A_COUNT, 32'h0, OKAY, "one-shot: COUNT is 0 after the end");
            rd_expect(A_STATUS, 32'h1, OKAY, "one-shot: EXPIRED set");
            wait_cycles(3 * len + 5);
            chk(rise_cnt == r0 + 1, "one-shot: still one interrupt");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "one-shot: clear expiry");
            chk(irq === 1'b0, "one-shot: irq low after clear");
            wait_cycles(2 * len + 5);
            chk(rise_cnt == r0 + 1, "one-shot: no second interrupt");
            chk(irq === 1'b0, "one-shot: irq stays low");
            rd_expect(A_STATUS, 32'h0, OKAY, "one-shot: EXPIRED stays clear");
        end
    endtask

    // ------------------------------------------------------------------
    // The suite, run once per lane
    // ------------------------------------------------------------------
    task run_suite;
        integer e;
        integer e2;
        integer r0;
        integer a_e;
        integer s_e;
        integer frozen;
        reg [31:0] d;
        reg [31:0] load_m;
        reg [1:0]  r;
        reg [1:0]  rw;
        begin
            do_reset;

            // 1. Reset values
            chk(awready === 1'b1, "reset: AWREADY high");
            chk(wready === 1'b1, "reset: WREADY high");
            chk(arready === 1'b1, "reset: ARREADY high");
            chk(bvalid === 1'b0, "reset: BVALID low");
            chk(rvalid === 1'b0, "reset: RVALID low");
            chk(irq === 1'b0, "reset: irq low");
            rd_expect(A_CTRL,   32'h0, OKAY, "reset: CTRL");
            rd_expect(A_LOAD,   32'h0, OKAY, "reset: LOAD");
            rd_expect(A_COUNT,  32'h0, OKAY, "reset: COUNT");
            rd_expect(A_STATUS, 32'h0, OKAY, "reset: STATUS");

            // 2. LOAD with partial strobes
            load_m = 32'h0;
            write_expect(A_LOAD, 32'hFFFFFFFF, 4'hF, OKAY, "LOAD write, strobe 1111");
            load_m = merge(load_m, 32'hFFFFFFFF, 4'hF);
            rd_expect(A_LOAD, load_m, OKAY, "LOAD read back, strobe 1111");
            write_expect(A_LOAD, 32'h12345678, 4'b0101, OKAY, "LOAD write, strobe 0101");
            load_m = merge(load_m, 32'h12345678, 4'b0101);
            rd_expect(A_LOAD, load_m, OKAY, "LOAD read back, strobe 0101");
            write_expect(A_LOAD, 32'h00000000, 4'b0000, OKAY, "LOAD write, strobe 0000");
            rd_expect(A_LOAD, load_m, OKAY, "LOAD unchanged by an empty strobe");
            write_expect(A_LOAD, 32'hAABBCCDD, 4'b1010, OKAY, "LOAD write, strobe 1010");
            load_m = merge(load_m, 32'hAABBCCDD, 4'b1010);
            rd_expect(A_LOAD, load_m, OKAY, "LOAD read back, strobe 1010");
            write_expect(A_LOAD, 32'h00000011, 4'b0001, OKAY, "LOAD write, strobe 0001");
            load_m = merge(load_m, 32'h00000011, 4'b0001);
            rd_expect(A_LOAD, load_m, OKAY, "LOAD read back, strobe 0001");
            write_expect(A_LOAD, 32'h99000000, 4'b1000, OKAY, "LOAD write, strobe 1000");
            load_m = merge(load_m, 32'h99000000, 4'b1000);
            rd_expect(A_LOAD, load_m, OKAY, "LOAD read back, strobe 1000");

            // 3. Channel orders, back-pressure, back-to-back
            axi_write_x(A_LOAD, 32'h01010101, 4'hF, 0, 3, 0, r);
            chk(r === OKAY, "AW before W: OKAY");
            rd_expect(A_LOAD, 32'h01010101, OKAY, "AW before W: data written");
            axi_write_x(A_LOAD, 32'h02020202, 4'hF, 3, 0, 0, r);
            chk(r === OKAY, "W before AW: OKAY");
            rd_expect(A_LOAD, 32'h02020202, OKAY, "W before AW: data written");
            axi_write_x(A_LOAD, 32'h03030303, 4'hF, 0, 0, 6, r);
            chk(r === OKAY, "B back-pressure: OKAY");
            rd_expect(A_LOAD, 32'h03030303, OKAY, "B back-pressure: data written");
            axi_write_x(A_LOAD, 32'h04040404, 4'hF, 2, 0, 4, r);
            chk(r === OKAY, "W first with B back-pressure: OKAY");
            axi_read_x(A_LOAD, 7, d, r);
            chk32(d, 32'h04040404, "R back-pressure: data");
            chk(r === OKAY, "R back-pressure: OKAY");
            write_expect(A_LOAD, 32'h05050505, 4'hF, OKAY, "back-to-back write 1");
            write_expect(A_LOAD, 32'h06060606, 4'hF, OKAY, "back-to-back write 2");
            rd_expect(A_LOAD, 32'h06060606, OKAY, "back-to-back: last write kept");

            // 4. A read and a write on one edge
            fork
                axi_write_x(A_LOAD, 32'hCAFEF00D, 4'hF, 0, 0, 0, rw);
                axi_read_x(A_LOAD, 0, d, r);
            join
            chk(rw === OKAY, "write beside a read: OKAY");
            chk(r === OKAY, "read beside a write: OKAY");
            chk(last_wr_edge == last_ar_edge, "read and write accepted on one edge");
            chk32(d, 32'h06060606, "read on the write edge returns the old value");
            rd_expect(A_LOAD, 32'hCAFEF00D, OKAY, "write beside a read took effect");

            // 5. SLVERR policy and no aliasing
            write_expect(A_LOAD, 32'd2, 4'hF, OKAY, "LOAD 2");
            write_expect(A_CTRL, 32'h1, 4'hF, OKAY, "start one-shot with IE 0");
            e = last_wr_edge;
            wait_until(e + 4);
            chk(irq === 1'b0, "no interrupt while IE is 0");
            rd_expect(A_STATUS, 32'h1, OKAY, "EXPIRED set with IE 0");
            write_expect(A_LOAD, 32'h00000777, 4'hF, OKAY, "LOAD 0x777");
            write_expect(8'h01, 32'hFFFFFFFF, 4'hF, SLVERR, "unaligned write 0x01: SLVERR");
            write_expect(8'h05, 32'hFFFFFFFF, 4'hF, SLVERR, "unaligned write 0x05: SLVERR");
            write_expect(8'h0A, 32'hFFFFFFFF, 4'hF, SLVERR, "unaligned write 0x0A: SLVERR");
            write_expect(8'h0D, 32'hFFFFFFFF, 4'hF, SLVERR, "unaligned write 0x0D: SLVERR");
            write_expect(8'h0F, 32'hFFFFFFFF, 4'hF, SLVERR, "unaligned write 0x0F: SLVERR");
            write_expect(A_COUNT, 32'hFFFFFFFF, 4'hF, SLVERR, "COUNT write: SLVERR");
            if (lane) begin
                write_expect(8'h10, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x10: SLVERR");
                write_expect(8'h14, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x14: SLVERR");
                write_expect(8'h18, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x18: SLVERR");
                write_expect(8'h1C, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x1C: SLVERR");
                write_expect(8'h20, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x20: SLVERR");
                write_expect(8'h44, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x44: SLVERR");
                write_expect(8'h80, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x80: SLVERR");
                write_expect(8'hFC, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0xFC: SLVERR");
                write_expect(8'h11, 32'hFFFFFFFF, 4'hF, SLVERR, "write 0x11: SLVERR");
            end
            rd_expect(A_CTRL,   32'h0,   OKAY, "CTRL unchanged by refused writes");
            rd_expect(A_LOAD,   32'h777, OKAY, "LOAD unchanged by refused writes");
            rd_expect(A_COUNT,  32'h0,   OKAY, "COUNT unchanged by refused writes");
            rd_expect(A_STATUS, 32'h1,   OKAY, "STATUS unchanged by refused writes");
            chk(irq === 1'b0, "irq low after refused writes");
            rd_expect(8'h01, 32'h0, SLVERR, "unaligned read 0x01: zero, SLVERR");
            rd_expect(8'h05, 32'h0, SLVERR, "unaligned read 0x05: zero, SLVERR");
            rd_expect(8'h06, 32'h0, SLVERR, "unaligned read 0x06: zero, SLVERR");
            rd_expect(8'h0F, 32'h0, SLVERR, "unaligned read 0x0F: zero, SLVERR");
            if (lane) begin
                rd_expect(8'h10, 32'h0, SLVERR, "read 0x10: zero, SLVERR");
                rd_expect(8'h14, 32'h0, SLVERR, "read 0x14: zero, SLVERR");
                rd_expect(8'h18, 32'h0, SLVERR, "read 0x18: zero, SLVERR");
                rd_expect(8'h1C, 32'h0, SLVERR, "read 0x1C: zero, SLVERR");
                rd_expect(8'h40, 32'h0, SLVERR, "read 0x40: zero, SLVERR");
                rd_expect(8'hFC, 32'h0, SLVERR, "read 0xFC: zero, SLVERR");
            end
            write_expect(A_STATUS, 32'h0, 4'hF, OKAY, "STATUS write 0: OKAY");
            rd_expect(A_STATUS, 32'h1, OKAY, "STATUS kept by writing 0");
            write_expect(A_STATUS, 32'h1, 4'b1110, OKAY, "STATUS write 1 without wstrb[0]");
            rd_expect(A_STATUS, 32'h1, OKAY, "STATUS kept without wstrb[0]");
            write_expect(A_STATUS, 32'hFFFFFFFF, 4'hF, OKAY, "STATUS write 1: OKAY");
            rd_expect(A_STATUS, 32'h0, OKAY, "STATUS cleared by writing 1");

            // 6. CTRL rules
            write_expect(A_CTRL, 32'h7, 4'b1110, OKAY, "CTRL write without wstrb[0]: OKAY");
            rd_expect(A_CTRL, 32'h0, OKAY, "CTRL unchanged without wstrb[0]");
            wait_cycles(4);
            rd_expect(A_COUNT, 32'h0, OKAY, "no count started without wstrb[0]");
            write_expect(A_CTRL, 32'hFFFFFFFA, 4'hF, OKAY, "CTRL write with upper bits");
            rd_expect(A_CTRL, 32'h2, OKAY, "CTRL bits 31:3 read as zero");
            write_expect(A_CTRL, 32'h0, 4'hF, OKAY, "CTRL write 0");
            rd_expect(A_CTRL, 32'h0, OKAY, "CTRL reads 0");

            // 7. One-shot counts timed to the cycle
            oneshot_run(32'd5);
            oneshot_run(32'd1);
            oneshot_run(32'd0);
            oneshot_run(32'd40);

            // 8. Interrupt enable on a pending expiry
            write_expect(A_CTRL, 32'h0, 4'hF, OKAY, "IE test: CTRL 0");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "IE test: clear");
            write_expect(A_LOAD, 32'd3, 4'hF, OKAY, "IE test: LOAD 3");
            write_expect(A_CTRL, 32'h1, 4'hF, OKAY, "IE test: start with IE 0");
            e = last_wr_edge;
            wait_until(e + 6);
            chk(irq === 1'b0, "pending expiry: irq low while IE 0");
            rd_expect(A_STATUS, 32'h1, OKAY, "pending expiry: EXPIRED set");
            r0 = rise_cnt;
            write_expect(A_CTRL, 32'h2, 4'hF, OKAY, "IE written 1 on a pending expiry");
            e2 = last_wr_edge;
            wait_cycles(2);
            chk(rise_cnt == r0 + 1, "irq rises when IE is written 1");
            chk(rise_edge[r0] == e2, "irq rises on the IE write edge");
            chk(irq === 1'b1, "irq high with IE and EXPIRED");
            write_expect(A_CTRL, 32'h0, 4'hF, OKAY, "IE written 0");
            chk(irq === 1'b0, "irq falls when IE is written 0");
            rd_expect(A_STATUS, 32'h1, OKAY, "EXPIRED kept when IE is written 0");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "IE test: clear");
            rd_expect(A_STATUS, 32'h0, OKAY, "IE test: EXPIRED cleared");

            // 9. Periodic counts over several periods (LOAD 10)
            write_expect(A_LOAD, 32'd10, 4'hF, OKAY, "periodic: LOAD 10");
            r0 = rise_cnt;
            write_expect(A_CTRL, 32'h7, 4'hF, OKAY, "periodic: start with IE");
            e = last_wr_edge;
            wait_until(e + 12);
            chk(rise_cnt == r0 + 1, "periodic: first period ends");
            chk(rise_edge[r0] == e + 10, "periodic: first period is LOAD cycles");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "periodic: clear 1");
            chk(irq === 1'b0, "periodic: irq low after clear 1");
            wait_until(e + 22);
            chk(rise_cnt == r0 + 2, "periodic: second period ends");
            chk(rise_edge[r0 + 1] == e + 20, "periodic: second period is LOAD cycles");
            rd_expect(A_CTRL, 32'h7, OKAY, "periodic: EN stays 1");
            wait_until(e + 28);
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "periodic: clear on a period end");
            chk(last_wr_edge == e + 30, "periodic: clear lands on the period end edge");
            chk(rise_cnt == r0 + 2, "periodic: no new rise while irq held");
            chk(irq === 1'b1, "count end beats a clear: irq stays high");
            rd_expect(A_STATUS, 32'h1, OKAY, "count end beats a clear: EXPIRED kept");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "periodic: clear 3");
            chk(irq === 1'b0, "periodic: irq low after clear 3");
            wait_until(e + 42);
            chk(rise_cnt == r0 + 3, "periodic: fourth period ends");
            chk(rise_edge[r0 + 2] == e + 40, "periodic: fourth period is LOAD cycles");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "periodic: clear 4");
            wait_until(e + 48);
            write_expect(A_CTRL, 32'h0, 4'hF, OKAY, "periodic: stop on a period end");
            chk(last_wr_edge == e + 50, "periodic: stop lands on the period end edge");
            rd_expect(A_COUNT, 32'd10, OKAY, "stop on a period end: COUNT reloaded");
            rd_expect(A_STATUS, 32'h1, OKAY, "stop on a period end: EXPIRED set");
            rd_expect(A_CTRL, 32'h0, OKAY, "stop on a period end: EN 0");
            chk(irq === 1'b0, "stop on a period end: irq low with IE 0");
            wait_cycles(30);
            rd_expect(A_COUNT, 32'd10, OKAY, "stopped periodic: COUNT holds");
            chk(rise_cnt == r0 + 3, "stopped periodic: no further interrupts");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "periodic: final clear");

            // 10. A stop freezes COUNT; COUNT read while running
            write_expect(A_LOAD, 32'd100, 4'hF, OKAY, "stop test: LOAD 100");
            r0 = rise_cnt;
            write_expect(A_CTRL, 32'h3, 4'hF, OKAY, "stop test: start with IE");
            e = last_wr_edge;
            wait_until(e + 10);
            axi_read_x(A_COUNT, 4, d, r);
            a_e = last_ar_edge;
            chk(r === OKAY, "COUNT read while running: OKAY");
            chk32(d, 100 - (a_e - 1 - e), "COUNT read while running, back-pressured");
            write_expect(A_CTRL, 32'h2, 4'hF, OKAY, "stop test: EN written 0");
            s_e = last_wr_edge;
            frozen = 100 - (s_e - e);
            rd_expect(A_COUNT, frozen, OKAY, "stop freezes COUNT");
            write_expect(A_COUNT, 32'h55, 4'hF, SLVERR, "COUNT write while stopped: SLVERR");
            rd_expect(A_COUNT, frozen, OKAY, "COUNT unchanged by a refused write");
            wait_cycles(120);
            rd_expect(A_COUNT, frozen, OKAY, "COUNT still frozen");
            chk(rise_cnt == r0, "no expiry after a stop");
            rd_expect(A_STATUS, 32'h0, OKAY, "stop test: no EXPIRED");
            rd_expect(A_CTRL, 32'h2, OKAY, "stop test: CTRL EN 0, IE 1");

            // 11. Restart while running
            write_expect(A_LOAD, 32'd30, 4'hF, OKAY, "restart: LOAD 30");
            r0 = rise_cnt;
            write_expect(A_CTRL, 32'h3, 4'hF, OKAY, "restart: first start");
            e = last_wr_edge;
            wait_until(e + 10);
            write_expect(A_CTRL, 32'h3, 4'hF, OKAY, "restart: EN written 1 again");
            e2 = last_wr_edge;
            wait_until(e2 + 33);
            chk(rise_cnt == r0 + 1, "restart: exactly one interrupt");
            chk(rise_edge[r0] == e2 + 30, "restart: count runs LOAD from the restart");
            rd_expect(A_CTRL, 32'h2, OKAY, "restart: EN clears itself");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "restart: clear");

            // 12. Restart on the count-end edge (write wins for EN and COUNT)
            write_expect(A_LOAD, 32'd8, 4'hF, OKAY, "end-edge restart: LOAD 8");
            r0 = rise_cnt;
            write_expect(A_CTRL, 32'h3, 4'hF, OKAY, "end-edge restart: start");
            e = last_wr_edge;
            wait_until(e + 6);
            write_expect(A_CTRL, 32'h3, 4'hF, OKAY, "end-edge restart: restart write");
            chk(last_wr_edge == e + 8, "end-edge restart: write lands on the end edge");
            chk(rise_cnt == r0 + 1, "end-edge restart: ending count still expires");
            chk(rise_edge[r0] == e + 8, "end-edge restart: expiry on the end edge");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "end-edge restart: clear");
            chk(irq === 1'b0, "end-edge restart: irq low after clear");
            wait_until(e + 19);
            chk(rise_cnt == r0 + 2, "end-edge restart: restarted count expires");
            chk(rise_edge[r0 + 1] == e + 16, "end-edge restart: restarted count is LOAD");
            rd_expect(A_CTRL, 32'h2, OKAY, "end-edge restart: EN clears itself");
            write_expect(A_STATUS, 32'h1, 4'hF, OKAY, "end-edge restart: final clear");

            // 13. Reset drops a held address; W-first write by hand
            @(negedge aclk);
            chk(awready === 1'b1, "idle: AWREADY high");
            awaddr  = A_LOAD;
            awvalid = 1'b1;
            @(negedge aclk);
            awvalid = 1'b0;
            chk(awready === 1'b0, "lone AW held: AWREADY low");
            chk(wready === 1'b1, "lone AW held: WREADY high");
            chk(bvalid === 1'b0, "lone AW: no response");
            aresetn = 1'b0;
            @(negedge aclk);
            @(negedge aclk);
            aresetn = 1'b1;
            chk(awready === 1'b1, "reset drops a held address");
            chk(bvalid === 1'b0, "reset: no response pending");
            wdata  = 32'h00001234;
            wstrb  = 4'hF;
            wvalid = 1'b1;
            @(negedge aclk);
            wvalid = 1'b0;
            chk(wready === 1'b0, "lone W held: WREADY low");
            chk(awready === 1'b1, "lone W held: AWREADY high");
            chk(bvalid === 1'b0, "no write completes without an address");
            awaddr  = A_LOAD;
            awvalid = 1'b1;
            @(negedge aclk);
            awvalid = 1'b0;
            chk(bvalid === 1'b1, "W then AW completes the write");
            chk(bresp === OKAY, "W then AW: OKAY");
            bready = 1'b1;
            @(negedge aclk);
            bready = 1'b0;
            chk(bvalid === 1'b0, "B handshake drops BVALID");
            rd_expect(A_LOAD, 32'h00001234, OKAY, "W-first write took effect");

            // 14. Reset during a count
            write_expect(A_LOAD, 32'd7, 4'hF, OKAY, "reset test: LOAD 7");
            write_expect(A_CTRL, 32'h7, 4'hF, OKAY, "reset test: periodic with IE");
            e = last_wr_edge;
            wait_until(e + 10);
            chk(irq === 1'b1, "reset test: irq high before reset");
            do_reset;
            chk(irq === 1'b0, "reset during count: irq low");
            chk(awready === 1'b1, "reset during count: AWREADY high");
            chk(arready === 1'b1, "reset during count: ARREADY high");
            rd_expect(A_CTRL,   32'h0, OKAY, "reset during count: CTRL");
            rd_expect(A_LOAD,   32'h0, OKAY, "reset during count: LOAD");
            rd_expect(A_COUNT,  32'h0, OKAY, "reset during count: COUNT");
            rd_expect(A_STATUS, 32'h0, OKAY, "reset during count: STATUS");
            r0 = rise_cnt;
            wait_cycles(60);
            chk(rise_cnt == r0, "no expiry after reset during a count");
            rd_expect(A_COUNT, 32'h0, OKAY, "COUNT stays 0 after reset");
        end
    endtask

    // ------------------------------------------------------------------
    // Main
    // ------------------------------------------------------------------
    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce))
            nonce = "none";
        lane = 1'b0;
        run_suite;
        lane = 1'b1;
        run_suite;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

    // Watchdog: only reached if the main sequence hangs.
    initial begin
        #2000000;
        $error("FAIL: watchdog: simulation did not finish");
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
        $finish;
    end

endmodule
